inline SENT::SENT(const SENT &o)
      : ID(o.ID),
        NAME(o.NAME),
        TYPE(o.TYPE),
        STATUS(o.STATUS),
        SITE_ID(o.SITE_ID),
        LATITUDE(o.LATITUDE),
        LONGITUDE(o.LONGITUDE),
        ALTITUDE(o.ALTITUDE),
        STATUS_TIME(o.STATUS_TIME),
        NOTES(o.NOTES) {
  MAINTENANCE.reserve(o.MAINTENANCE.size());
  for (const auto &MAINTENANCE_ : o.MAINTENANCE) { MAINTENANCE.emplace_back((MAINTENANCE_) ? new sensorMaintenanceEventT(*MAINTENANCE_) : nullptr); }
  PLANS.reserve(o.PLANS.size());
  for (const auto &PLANS_ : o.PLANS) { PLANS.emplace_back((PLANS_) ? new sensorPlanT(*PLANS_) : nullptr); }
  STATISTICS.reserve(o.STATISTICS.size());
  for (const auto &STATISTICS_ : o.STATISTICS) { STATISTICS.emplace_back((STATISTICS_) ? new sensorStatsT(*STATISTICS_) : nullptr); }
}

